/**
 * THERMAL RECEIPT BUILDER — 80mm
 * Clean professional layout
 */

const QR_REVIEW_SRC = 'data:image/jpeg;base64,';

function buildThermalReceipt({
  receiptTitle = 'Original Receipt',
  id         = '',
  date       = '',
  time       = '',
  cashier    = '',
  payment    = 'CASH',
  itemsHtml  = '',
  subtotal   = 0,
  discount      = 0,
  cashback      = 0,
  cashReceived  = 0,
  delivery      = 0,
  total      = 0,
  copies     = 1,
  copyLabels = [],
  extraInfo  = []
}) {

  function copyHTML(label) {
    label = label || '';

    var extraRows = extraInfo.map(function(r) {
      return '<div class="mrow"><span class="ml">' + r.label + '</span><span class="mv">' + r.value + '</span></div>';
    }).join('');

    var discountRow = discount > 0
      ? '<div class="mrow"><span class="ml">Discount</span><span class="mv">- Rs ' + formatCurrency(discount) + '</span></div>'
      : '';

    var cashbackRow = (cashback > 0)
      ? '<div class="mrow"><span class="ml">Cashback</span><span class="mv cashback-val">Rs ' + formatCurrency(cashback) + '</span></div>'
      : '';

    var cashReceivedRow = (cashReceived > 0)
      ? '<div class="mrow cash-recv-row"><span class="ml">Cash Received</span><span class="mv">Rs ' + formatCurrency(cashReceived) + '</span></div>'
      : '';

    var deliveryRow = delivery > 0
      ? '<div class="mrow"><span class="ml">Delivery</span><span class="mv">Rs ' + formatCurrency(delivery) + '</span></div>'
      : '';

    var cashierRow = cashier
      ? '<div class="mrow"><span class="ml">Cashier</span><span class="mv">' + cashier + '</span></div>'
      : '';

    return '<div class="paper">'

      /* ── copy label (online orders only) ── */
      + (label ? '<div class="copy-label">' + label + '</div>' : '')

      /* ── LOGO ── */
      + '<div class="logo-wrap">'
      +   '<div class="logo-lbh">LBH</div>'
      +   '<div class="logo-name">LAJPAL BRAND HUB</div>'
      +   '<div class="logo-url">www.lajpalbrandhub.com</div>'
      +   '<div class="logo-detail">+92 311 1122998</div>'
      +   '<div class="logo-detail">Karimabad, Karachi</div>'
      +   '<div class="logo-social">fb: lajpalbrandhub &nbsp;|&nbsp; ig: lajpalbrandhub</div>'
      + '</div>'

      /* ── badge ── */
      + '<div class="badge">' + receiptTitle + '</div>'

      /* ── meta ── */
      + '<div class="meta-block">'
      +   '<div class="mrow"><span class="ml">Invoice #</span><span class="mv">' + id + '</span></div>'
      +   '<div class="mrow"><span class="ml">Date</span><span class="mv">' + date + '</span></div>'
      +   '<div class="mrow"><span class="ml">Time</span><span class="mv">' + time + '</span></div>'
      +   cashierRow
      +   '<div class="mrow"><span class="ml">Payment</span><span class="mv bold">' + payment + '</span></div>'
      +   extraRows
      + '</div>'

      + '<hr class="solid">'

      /* ── items header ── */
      + '<div class="items-hdr">'
      +   '<span>Product Description</span>'
      +   '<span>Qty &nbsp; Price &nbsp;&nbsp;&nbsp;&nbsp; Total</span>'
      + '</div>'
      + '<div class="items-lbl">&#8212; Sales Items &#8212;</div>'

      /* ── items ── */
      + itemsHtml

      + '<hr class="solid">'

      /* ── totals ── */
      + '<div class="mrow"><span class="ml">Subtotal</span><span class="mv">Rs ' + formatCurrency(subtotal) + '</span></div>'
      + discountRow
      + deliveryRow

      + '<hr class="solid">'

      /* ── invoice value ── */
      + '<div class="inv-val"><span>Invoice Value</span><span>Rs ' + formatCurrency(total) + '</span></div>'

      + '<hr class="solid">'

      /* ── payments ── */
      + '<div class="sec-ttl">Payments</div>'
      + '<hr class="dash">'
      + '<div class="mrow"><span class="ml">' + payment + '</span><span class="mv">Rs ' + formatCurrency(total) + '</span></div>'
      + cashReceivedRow
      + (cashback > 0
          ? '<div class="mrow"><span class="ml bold" style="color:#1a6b3c;">Cashback</span><span class="mv bold" style="color:#1a6b3c;">Rs ' + formatCurrency(cashback) + '</span></div>'
          : '')
      + (cashReceived <= 0 ? '<div class="mrow muted"><span class="ml">Change Due</span><span class="mv">Rs 0</span></div>' : '')

      + '<hr class="solid" style="margin-top:8px">'

      /* ── QR review ── */
      + '<div class="sec-ttl">Review Us</div>'
      + '<hr class="dash">'
      + '<div class="qr-wrap">'
      +   '<img src="' + QR_REVIEW_SRC + '" alt="QR">'
      +   '<div class="qr-txt">&#128247; Scan to Review Us</div>'
      +   '<div class="qr-sub">Your feedback matters to us!</div>'
      + '</div>'

      + '<hr class="solid" style="margin-top:8px">'

      /* ── footer ── */
      + '<div class="footer">'
      +   '<div>Thank you for shopping at Lajpal Brand Hub!</div>'
      +   '<div style="margin-top:3px">www.lajpalbrandhub.com</div>'
      + '</div>'

      + '<hr class="dash" style="margin-top:6px">'

      + '<div class="dev">'
      +   'Software Developed by Nanogramics<br>'
      +   'nanogramics.tech'
      + '</div>'

      + '</div>';
  }

  /* ── assemble copies ── */
  var body = '';
  if (copies === 2) {
    var l1 = copyLabels[0] || '— Shop Copy —';
    var l2 = copyLabels[1] || '— Customer Copy —';
    body = '<div class="wrap-screen">'
         +   '<div class="col">' + copyHTML(l1) + '</div>'
         +   '<div class="col-sep"></div>'
         +   '<div class="col">' + copyHTML(l2) + '</div>'
         + '</div>'
         + '<div class="print-stack">'
         +   copyHTML(l1)
         +   '<div class="cut">&#9986; - - - - - - - - - - - - - - - - - - - -</div>'
         +   copyHTML(l2)
         + '</div>';
  } else {
    body = copyHTML('');
  }

  var css = `
    @page { size: 80mm auto; margin: 0; }

    * { margin:0; padding:0; box-sizing:border-box; }

    body {
      background: #e8e0d0;
      font-family: 'Courier New', Courier, monospace;
      font-size: 11px;
      font-weight: 500;
      color: #000;
      display: flex;
      justify-content: center;
      padding: 12px 0;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      text-rendering: optimizeLegibility;
    }

    /* crisp normal-weight text on thermal head — thin strokes dither into blur otherwise */
    .meta-block, .mrow, .ml, .mv,
    .item-detail, .footer, .dev,
    .qr-sub, .logo-detail, .logo-social, .logo-url,
    .items-hdr {
      font-weight: 500;
      -webkit-text-stroke: 0.25px #000;
    }

    /* ─ paper ─ */
    .paper {
      width: 72mm;
      background: #fff;
      padding: 6mm 3mm 7mm;
      box-shadow: 0 2px 12px rgba(0,0,0,0.25);
    }

    /* ─ logo ─ */
    .logo-wrap   { text-align: center; padding-bottom: 6px; }
    .logo-lbh    {
      font-family: Georgia, 'Times New Roman', serif;
      font-size: 36px;
      font-weight: 900;
      letter-spacing: 10px;
      padding-left: 10px;   /* offset trailing letter-spacing */
      line-height: 1.1;
      color: #000;
    }
    .logo-name   { font-size: 11px; font-weight: 700; letter-spacing: 2.5px; margin-top: 2px; }
    .logo-url    { font-size: 8.5px; color: #555; margin-top: 2px; }
    .logo-detail { font-size: 9px;   color: #333; margin-top: 1px; }
    .logo-social { font-size: 8.5px; color: #555; margin-top: 2px; }

    /* ─ badge ─ */
    .badge {
      text-align: center;
      border-top:    1.5px solid #000;
      border-bottom: 1.5px solid #000;
      padding:  3px 0;
      margin:   6px 0;
      font-size: 11.5px;
      font-weight: 700;
      letter-spacing: 1px;
    }

    /* ─ copy label ─ */
    .copy-label {
      text-align: center;
      font-size: 8.5px;
      color: #888;
      border: 1px dashed #bbb;
      padding: 2px 0;
      margin-bottom: 4px;
    }

    /* ─ meta rows ─ */
    .meta-block { font-size: 9.5px; line-height: 1.7; }
    .mrow  { display: flex; justify-content: space-between; }
    .ml    { color: #444; white-space: nowrap; padding-right: 4px; }
    .mv    { text-align: right; }
    .bold  { font-weight: 700; }
    .muted { color: #666; font-size: 9px; }

    /* ─ dividers ─ */
    .solid { border: none; border-top: 1.5px solid #000; margin: 5px 0; }
    .dash  { border: none; border-top: 1px  dashed #666; margin: 4px 0; }

    /* ─ items ─ */
    .items-hdr {
      display: flex;
      justify-content: space-between;
      font-size: 9px;
      font-weight: 700;
      padding: 3px 0 2px;
      border-bottom: 1px solid #333;
    }
    .items-lbl {
      text-align: center;
      font-size: 9px;
      font-weight: 700;
      padding: 3px 0 2px;
    }

    /* item block — built in sales.js / online.js */
    .item-block  { margin: 4px 0 2px; }
    .item-name   { font-weight: 700; font-size: 10.5px; margin-bottom: 1px; }
    .item-detail {
      display: flex;
      justify-content: space-between;
      font-size: 9.5px;
      color: #333;
    }
    .item-detail .amt { font-weight: 700; color: #000; }
    .item-sep { border: none; border-top: 0.5px dotted #bbb; margin: 3px 0; }

    /* ─ totals ─ */
    .inv-val {
      display: flex;
      justify-content: space-between;
      font-size: 13px;
      font-weight: 900;
      padding: 4px 0 3px;
    }

    /* ─ section title ─ */
    .sec-ttl {
      text-align: center;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 1.5px;
      padding: 3px 0 2px;
    }

    /* ─ QR ─ */
    .cashback-val { color: #1a6b3c; font-weight: 700; }
    .cash-recv-row { border-top: 0.5px dashed #ccc; padding-top: 3px; margin-top: 2px; }
    .qr-wrap { text-align: center; padding: 7px 0 4px; }
    .qr-wrap img {
      width: 100px; height: 100px;
      display: block;
      margin: 0 auto 5px;
      image-rendering: pixelated;
      image-rendering: crisp-edges;
    }
    .qr-txt { font-size: 10.5px; font-weight: 700; }
    .qr-sub { font-size: 8.5px;  color: #555; margin-top: 2px; }

    /* ─ footer / dev ─ */
    .footer { text-align: center; font-size: 9px;  color: #444; line-height: 1.65; }
    .dev    { text-align: center; font-size: 8px;  color: #888; line-height: 1.65; margin-top: 6px; }

    /* ─ 2-copy screen layout ─ */
    .wrap-screen { display: flex; align-items: flex-start; }
    .col { width: 72mm; }
    .col-sep {
      width: 1px;
      background: repeating-linear-gradient(
        to bottom, #999 0, #999 5px, transparent 5px, transparent 10px
      );
      align-self: stretch;
      margin: 0 4px;
    }
    .print-stack { display: none; }
    .cut { font-size: 9px; color: #aaa; margin: 5mm 0; }

    /* ─ print button ─ */
    @media print {
      body  {
        background: #fff;
        padding: 0;
        width: 80mm;
        color: #000;
        -webkit-font-smoothing: none;
        -moz-osx-font-smoothing: unset;
        text-rendering: geometricPrecision;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
      }
      body * {
        color: #000 !important;
        text-shadow: none !important;
      }
      .paper {
        box-shadow: none;
        background: #fff;
        width: 72mm;
        padding: 3mm 2mm;
      }
      .wrap-screen { display: none  !important; }
      .print-stack { display: block !important; }
    }
  `;


  return '<!DOCTYPE html><html><head>'
       + '<meta charset="UTF-8">'
       + '<title>Receipt ' + id + '</title>'
       + '<style>' + css + '</style>'
       + '</head><body>'
       + body
       + '</body></html>';
}
